import { createRequire } from 'node:module';
import { mkdir, readFile, writeFile, access, symlink, rm } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { z } from 'zod';
import type { VideoDocument } from '@codex-ux/video-domain';
import { digest } from './files.ts';
import { videoDirectory } from '../video/paths.ts';
import { HttpError } from '../errors.ts';

const require = createRequire(import.meta.url);
const execute = promisify(execFile);
export const runtimeVersions = {
  react: '19.2.8',
  'react-dom': '19.2.8',
  remotion: '4.0.522',
  '@remotion/player': '4.0.522',
};
export const runtimeAliases = Object.fromEntries(
  Object.keys(runtimeVersions).map((name) => [
    name,
    dirname(require.resolve(`${name}/package.json`)),
  ]),
);
const pending = new Map<string, Promise<string>>();
/** Project dependencies are disposable build inputs; never restore node_modules from history. */
export async function dependencyDirectory(root: string, id: string, doc: VideoDocument) {
  const packageText = doc.files['package.json']?.text;
  if (!packageText) return join(dirname(require.resolve('../../package.json')), 'node_modules');
  const pkg = z
    .object({
      dependencies: z.record(z.string(), z.string()).optional(),
      devDependencies: z.record(z.string(), z.string()).optional(),
    })
    .passthrough()
    .parse(JSON.parse(packageText));
  const dependencies = { ...pkg.devDependencies, ...pkg.dependencies };
  for (const [name, version] of Object.entries(runtimeVersions)) {
    if (dependencies[name] && dependencies[name] !== version)
      throw new HttpError(
        400,
        `This Remotion adapter requires ${name} ${version}; found ${dependencies[name]}.`,
      );
  }
  const extra = Object.keys(dependencies).filter((name) => !(name in runtimeVersions));
  if (!extra.length) return join(dirname(require.resolve('../../package.json')), 'node_modules');
  const lock = doc.files['pnpm-lock.yaml'];
  if (!lock)
    throw new HttpError(
      400,
      'Remotion projects with extra dependencies need package.json and pnpm-lock.yaml.',
    );
  const { blobsDirectory } = await import('../video/paths.ts');
  const lockText = await readFile(join(blobsDirectory(root, id), lock.hash), 'utf8');
  const key = digest(packageText + '\n' + lockText);
  const dir = join(videoDirectory(root, id), 'dependencies', key);
  const existing = pending.get(dir);
  if (existing) return existing;
  const task = (async () => {
    try {
      await access(join(dir, '.ready'));
      return join(dir, 'node_modules');
    } catch {
      /* Fresh dependency environment. */
    }
    await mkdir(dir, { recursive: true });
    await writeFile(join(dir, 'package.json'), packageText);
    await writeFile(join(dir, 'pnpm-lock.yaml'), lockText);
    // Disable scripts and repository/global pnpm hooks. The app never runs a project's install script.
    await writeFile(join(dir, 'pnpm-workspace.yaml'), 'packages: []\n');
    try {
      await execute(
        process.execPath,
        [
          join(dirname(require.resolve('pnpm/package.json')), 'bin/pnpm.cjs'),
          'install',
          '--frozen-lockfile',
          '--ignore-scripts',
          '--ignore-pnpmfile',
          '--config.manage-package-manager-versions=false',
        ],
        { cwd: dir, timeout: 180000, maxBuffer: 2 * 1024 * 1024 },
      );
      await writeFile(join(dir, '.ready'), 'ready');
      return join(dir, 'node_modules');
    } catch (error) {
      throw new HttpError(
        422,
        `Could not prepare Remotion dependencies: ${error instanceof Error ? error.message : 'installation failed'}`,
      );
    }
  })();
  pending.set(dir, task);
  try {
    return await task;
  } finally {
    pending.delete(dir);
  }
}
export async function linkDependencies(directory: string, target: string) {
  await rm(join(directory, 'node_modules'), { recursive: true, force: true });
  await symlink(target, join(directory, 'node_modules'), 'dir');
}

import { createHash } from 'node:crypto';
import { mkdir, readFile, readdir, stat, writeFile, copyFile, realpath } from 'node:fs/promises';
import { join, relative, resolve, sep } from 'node:path';
import {
  sourceSchema,
  hyperframesMetadata,
  videoSchema,
  type ProjectFiles,
  type VideoDocument,
  type Asset,
} from '@codex-ux/video-domain';
import { contained } from '../storage/paths.ts';
import { videoDirectory, blobsDirectory } from '../video/paths.ts';
import { HttpError } from '../errors.ts';
import { probeVideo } from '../video/probe.ts';

export const digest = (data: string | Buffer) => createHash('sha256').update(data).digest('hex');
export const excludedSourceNames: ReadonlySet<string> = new Set([
  '.git',
  '.DS_Store',
  'node_modules',
  'dist',
  'build',
  '.cache',
  '.next',
  '.video-editor',
]);
const editable = /\.(?:html?|[cm]?js|jsx|tsx?|css|json)$/i;
export async function inventory(directory: string) {
  const root = await realpath(directory);
  const files: { path: string; size: number; mtime: number; ctime: number }[] = [];
  async function walk(dir: string) {
    for (const entry of (await readdir(dir, { withFileTypes: true })).sort((a, b) =>
      a.name.localeCompare(b.name),
    )) {
      if (excludedSourceNames.has(entry.name)) continue;
      const file = join(dir, entry.name);
      if (entry.isSymbolicLink())
        throw new HttpError(
          400,
          `Resolve source symbolic links before importing: ${relative(root, file)}`,
        );
      if (entry.isDirectory()) await walk(file);
      else if (entry.isFile()) {
        const info = await stat(file);
        files.push({
          path: relative(root, file).split(sep).join('/'),
          size: info.size,
          mtime: info.mtimeMs,
          ctime: info.ctimeMs,
        });
        if (files.length > 20000) throw new HttpError(400, 'Project exceeds 20,000 source files.');
      }
    }
  }
  await walk(root);
  if (files.reduce((sum, file) => sum + file.size, 0) > 2 * 1024 ** 3)
    throw new HttpError(400, 'Project exceeds the 2 GB snapshot limit.');
  return { files, signature: digest(JSON.stringify(files)) };
}
async function saveBlob(root: string, id: string, bytes: Buffer) {
  const hash = digest(bytes);
  await mkdir(blobsDirectory(root, id), { recursive: true });
  await writeFile(join(blobsDirectory(root, id), hash), bytes, { flag: 'wx' }).catch(
    (error: NodeJS.ErrnoException) => {
      if (error.code !== 'EEXIST') throw error;
    },
  );
  return hash;
}
export async function captureFiles(
  root: string,
  id: string,
  directory: string,
): Promise<ProjectFiles> {
  const before = await inventory(directory);
  const files: ProjectFiles = {};
  let textSize = 0;
  for (const file of before.files) {
    const bytes = await readFile(contained(directory, file.path));
    const hash = await saveBlob(root, id, bytes);
    const text = editable.test(file.path) ? bytes.toString('utf8') : undefined;
    textSize += text === undefined ? 0 : bytes.length;
    if (textSize > 8 * 1024 * 1024) throw new HttpError(400, 'Editable source exceeds 8 MB.');
    files[file.path] = { hash, size: bytes.length, ...(text === undefined ? {} : { text }) };
  }
  if ((await inventory(directory)).signature !== before.signature)
    throw new HttpError(409, 'Project files changed during capture. Waiting for a stable save.');
  return files;
}
export async function inspectFiles(
  root: string,
  id: string,
  files: ProjectFiles,
  name: string,
  assets: Asset[] = [],
): Promise<VideoDocument> {
  const manifest = files['video.json']?.text;
  const videos = Object.keys(files).filter(
    (path) => !path.includes('/') && /\.(mp4|webm)$/i.test(path),
  );
  const source = sourceSchema.parse(
    manifest === undefined
      ? files['index.html']
        ? { kind: 'hyperframes', entry: 'index.html' }
        : videos.length === 1
          ? { kind: 'media', entry: videos[0] }
          : (() => {
              throw new HttpError(
                400,
                'Add video.json to identify the video source, or import a single video file.',
              );
            })()
      : JSON.parse(manifest),
  );
  const entry = files[source.entry];
  if (!entry) throw new HttpError(400, `Video source entry is missing: ${source.entry}`);
  let metadata: { width: number; height: number; duration: number; fps: number | null };
  switch (source.kind) {
    case 'hyperframes':
      metadata = { ...hyperframesMetadata(entry.text ?? ''), fps: source.fps };
      break;
    case 'remotion':
      metadata = {
        width: source.width,
        height: source.height,
        duration: source.durationInFrames / source.fps,
        fps: source.fps,
      };
      break;
    case 'media': {
      if (!/\.(mp4|webm)$/i.test(source.entry))
        throw new HttpError(415, 'Use an MP4 or WebM source.');
      metadata = {
        ...(await probeVideo(contained(blobsDirectory(root, id), entry.hash))),
        fps: null,
      };
