      }
      await rm(backup, { recursive: true, force: true });
      const signature = (await inventory(directory)).signature;
      this.scans.set(id, { signature, since: Date.now(), accepted: signature });
    } finally {
      await rm(stage, { recursive: true, force: true });
    }
  }
}

