import { createReadStream } from 'node:fs';
import { extname } from 'node:path';
import type { IncomingMessage, ServerResponse } from 'node:http';
import { HttpError } from './errors.ts';

const types: Record<string, string> = {
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.mjs': 'text/javascript',
  '.wasm': 'application/wasm',
  '.glb': 'model/gltf-binary',
  '.gltf': 'model/gltf+json',
  '.avif': 'image/avif',
  '.css': 'text/css',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.webp': 'image/webp',
  '.gif': 'image/gif',
  '.mp4': 'video/mp4',
  '.webm': 'video/webm',
  '.mp3': 'audio/mpeg',
  '.wav': 'audio/wav',
  '.ogg': 'audio/ogg',
  '.m4a': 'audio/mp4',
  '.woff2': 'font/woff2',
  '.woff': 'font/woff',
  '.ttf': 'font/ttf',
  '.otf': 'font/otf',
  '.svg': 'image/svg+xml',
};
export async function serveFile(
  req: IncomingMessage,
  res: ServerResponse,
  file: string,
  cache = false,
) {
  let info;
  try {
    info = await stat(file);
  } catch {
    throw new HttpError(404, 'File not found.');
  }
  if (!info.isFile()) throw new HttpError(404, 'File not found.');
  res.setHeader('Content-Type', types[extname(file)] ?? 'application/octet-stream');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Accept-Ranges', 'bytes');
  res.setHeader('Cache-Control', cache ? 'private, max-age=31536000, immutable' : 'no-cache');
  let start = 0,
    end = info.size - 1;
  if (req.headers.range) {
    const match = /^bytes=(\d*)-(\d*)$/.exec(req.headers.range);
    if (!match) throw new HttpError(416, 'Invalid byte range.');
    if (!match[1]) start = Math.max(0, info.size - Number(match[2]));
    else {
      start = Number(match[1]);
      if (match[2]) end = Math.min(end, Number(match[2]));
    }
    if (start > end || start >= info.size) {
      res.setHeader('Content-Range', `bytes */${info.size}`);
      throw new HttpError(416, 'Range exceeds file size.');
    }
    res.statusCode = 206;
    res.setHeader('Content-Range', `bytes ${start}-${end}/${info.size}`);
  }
  res.setHeader('Content-Length', Math.max(0, end - start + 1));
  if (req.method === 'HEAD' || info.size === 0) {
    res.end();
    return;
  }
  const stream = createReadStream(file, { start, end });
  stream.on('error', () => res.destroy());
  stream.pipe(res);
}

import { lstat, readdir, realpath } from 'node:fs/promises';
import { join, sep } from 'node:path';
import { HttpError } from '../errors.ts';

/** List one directory without following links outside the workspace. */
export async function listWorkspaceFiles(root: string, path: string) {
  const parts = path.split('/').filter(Boolean);
  if (parts.some((part) => part === '..' || part === '.' || part.includes('\\')))
    throw new HttpError(400, 'Invalid directory path.');
  let directory = root;
  for (const part of parts) {
    directory = join(directory, part);
    const stat = await lstat(directory);
    if (stat.isSymbolicLink() || !stat.isDirectory())
      throw new HttpError(403, 'Only workspace directories can be opened.');
  }
  const resolved = await realpath(directory);
  const base = await realpath(root);
  if (resolved !== base && !resolved.startsWith(base + sep))
    throw new HttpError(403, 'Path is outside the workspace.');
  const entries = await readdir(directory, { withFileTypes: true });
  return {
    path: parts.join('/'),
    entries: entries
      .filter((entry) => entry.name !== '.DS_Store')
      .map((entry) => ({
        name: entry.name,
        kind: entry.isSymbolicLink() ? 'link' : entry.isDirectory() ? 'directory' : 'file',
      }))
      .sort((a, b) =>
        a.kind === b.kind ? a.name.localeCompare(b.name) : a.kind === 'directory' ? -1 : 1,
      ),
  };
}

